sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var gr = new GlideRecord('sys_user');
  gr.addQuery('correlation_id', 'atf-no-such-correlation-id-0003');
  gr.addQuery('active', true);
  gr.query();
  if (gr.getRowCount() !== 0) {
    stepResult.setFailed('fixture drifted: an active user already carries this ATF-reserved correlation_id');
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var dupCorrelationId = 'atf-ambiguous-correlation-id-0004';
  function makeUser(userName) {
    var u = new GlideRecord('sys_user');
    u.initialize();
    u.setValue('user_name', userName);
    u.setValue('correlation_id', dupCorrelationId);
    u.setValue('active', true);
    return u.insert();
  }
  var id1 = makeUser('atf.sam.dup1');
  var id2 = makeUser('atf.sam.dup2');
  if (!id1 || !id2) { stepResult.setFailed('failed to seed the two ambiguous-correlation fixtures'); return; }

  var gr = new GlideRecord('sys_user');
  gr.addQuery('correlation_id', dupCorrelationId);
  gr.addQuery('active', true);
  gr.query();
  var count = gr.getRowCount();
  if (count <= 1) {
    stepResult.setFailed('expected an ambiguous match (>1 active user for one correlation_id), got ' + count);
    return;
  }
  // resolveSubject() explicitly refuses when count > 1 rather than taking gr.next() blindly.
  stepResult.setSuccess();
})(outputs, steps, stepResult);
